    openrouter: { label: "OpenRouter activity", url: "https://openrouter.ai/activity" },
    "google-vertex": { label: "Google Cloud billing", url: "https://console.cloud.google.com/billing" },
    google: { label: "Google AI Studio usage", url: "https://aistudio.google.com" },
  };
  return providers.flatMap((provider) => known[provider.id] ? [known[provider.id]] : []);
}

function mcpStatus(server: RawMcpServer): OpenCodeDiscovery["mcpServers"][number]["status"] {
  const status = typeof server.status === "string" ? server.status : server.status?.status;
  if (status === "connected" || status === "pending" || status === "disabled" || status === "failed" || status === "needs_auth") return status;
  return "pending";
}

export function normalizeDiscovery(input: RawDiscoveryInput): OpenCodeDiscovery {
  const compatibility = checkVersionCompatibility(input.version);
  const providerById = new Map(input.providers.map((provider) => [provider.id, provider]));
  const models = input.models.map((model) => normalizeModel(model, providerById.get(model.providerID)));
  const providers = normalizeProviders(input.models, input.providers, input.integrations);
  const config = input.config ?? [];
  const formatters = config.flatMap((entry) => formatterEntries(entry.info).formatters);
  const lspServers = config.flatMap((entry) => formatterEntries(entry.info).lspServers);
  const limitations: string[] = [
    "Provider credentials and quota remain owned by OpenCode; this application never reads or stores provider API keys.",
    "Session cost and token totals appear only when OpenCode and the provider return usage.",
    "Model variants are limited to the selected model's reported variant IDs; there is no universal reasoning scale.",
    "A separate HTTP tool catalog is not exposed by OpenCode 2.0.32; tool availability is governed by the selected agent and permissions.",
    "Formatter and LSP entries reflect configuration from OpenCode, not live process health.",
  ];
  if (!compatibility.compatible) limitations.push(compatibility.warning ?? "The installed OpenCode server is not compatible.");
  else if (compatibility.warning) limitations.push(compatibility.warning);
  if (models.some((model) => model.local)) {
    limitations.push("Local model resource limits depend on the machine and runtime; OpenCode reports catalog limits but not free RAM or VRAM.");
  }

  return {
    server: {
      version: input.version,
      compatible: compatibility.compatible,
      testedVersion: TESTED_OPENCODE_VERSION,
      warning: compatibility.warning,
    },
    providers,
    models,
    agents: (input.agents ?? []).filter((agent) => !agent.hidden).map((agent) => ({
      id: agent.id,
      name: agent.name ?? agent.id,
      mode: agent.mode ?? "primary",
      hidden: Boolean(agent.hidden),
      description: agent.description ?? null,
      permissionCount: Array.isArray(agent.permissions) ? agent.permissions.length : 0,
    })),
    roles: mapRoles(input.agents ?? []),
    permissions: (input.permissions ?? []).map((request) => ({
      id: request.id,
      sessionID: request.sessionID,
      action: request.action,
      resources: request.resources ?? [],
      message: request.message ?? null,
    })),
    commands: (input.commands ?? []).map((command) => ({
      name: command.name,
      description: command.description ?? null,
    })),
    skills: (input.skills ?? []).map((skill) => ({
      id: skill.id,
      name: skill.name ?? skill.id,
      description: skill.description ?? null,
    })),
    mcpServers: (input.mcpServers ?? []).map((server) => ({
      name: server.name,
      status: mcpStatus(server),
      error: typeof server.status === "object" ? server.status?.error ?? null : null,
    })),
    formatters,
    lspServers,
    capabilities: [
      { id: "models", label: "Models and limits", supported: models.length > 0, detail: `${models.length} model(s) reported by the server.` },
      { id: "variants", label: "Model variants", supported: models.some((model) => model.variants.length > 0), detail: "Only variants attached to each model are selectable." },
      { id: "agents", label: "Agents", supported: (input.agents ?? []).length > 0, detail: `${(input.agents ?? []).length} agent(s) visible.` },
      { id: "permissions", label: "Permission requests", supported: true, detail: "Pending requests are read from OpenCode and never auto-approved." },
      { id: "commands", label: "Commands", supported: (input.commands ?? []).length > 0, detail: `${(input.commands ?? []).length} command(s) discovered.` },
      { id: "skills", label: "Skills", supported: (input.skills ?? []).length > 0, detail: `${(input.skills ?? []).length} skill(s) discovered.` },
      { id: "mcp", label: "MCP servers", supported: true, detail: `${(input.mcpServers ?? []).length} server(s) reported.` },
      { id: "formatters", label: "Formatters", supported: formatters.length > 0, detail: "Configuration presence only; no live formatter health probe." },
      { id: "lsp", label: "LSP servers", supported: lspServers.length > 0, detail: "Configuration presence only; no live LSP health probe." },
      { id: "sessions", label: "Session list and resume", supported: true, detail: "Limited to sessions referenced by this project." },
      { id: "interrupt", label: "Interrupt", supported: true, detail: "Requires a session owned by this project." },
      { id: "fork", label: "Fork", supported: true, detail: "Requires a non-empty session; the server rejects empty forks." },
      { id: "compact", label: "Compact", supported: true, detail: "Queues an OpenCode compaction request; it may report nothing to compact." },
      { id: "revert", label: "Revert", supported: true, detail: "Stage, clear, or commit requires a message boundary and an idle session." },
      { id: "tools", label: "Tool catalog", supported: false, detail: "Not exposed as a separate HTTP catalog by the installed server." },
      { id: "usage", label: "Usage totals", supported: true, detail: "Shown only when OpenCode returns session cost or token totals." },
      { id: "quota", label: "Provider quota", supported: false, detail: "Quota and balance are not available through the OpenCode HTTP API." },
    ],
    usage: {
      supported: true,
      quotaSupported: false,
      links: usageLinks(providers),
      detail: "Session cost and token totals come from OpenCode. Quota and balance require the provider console.",
    },
    limitations,
  };
}

import { chmod, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { z } from "zod";
import {
  connectionStatusSchema,
  type ConnectionStatus,
  type DeploymentMode,
  type DiscoveredModel,
  type OpenCodeDiscovery,
} from "../../shared/opencode.ts";
import type { ModelRef } from "../workflow/model.ts";
import {
  checkVersionCompatibility,
  classifyConnectionError,
  ConnectionConfigError,
  createNativeClient,
  redactSecrets,
  validateServerUrl,
  type NativeClientOptions,
} from "./client.ts";
import {
  normalizeDiscovery,
  type RawAgent,
  type RawCommand,
  type RawConfigEntry,
  type RawDiscoveryInput,
  type RawIntegration,
  type RawMcpServer,
  type RawModel,
  type RawPermissionRequest,
  type RawProvider,
  type RawSkill,
} from "./discovery.ts";

export interface NativeClientLike {
  server: { info: () => Promise<{ version: string }> };
  model: { list: () => Promise<{ data: RawModel[] }> };
  provider: { list: () => Promise<{ data: RawProvider[] }> };
  integration: { list: () => Promise<{ data: RawIntegration[] }> };
  agent: { list: () => Promise<{ data: RawAgent[] }> };
  permission: { request: { list: () => Promise<{ data: RawPermissionRequest[] }> } };
  command: { list: () => Promise<{ data: RawCommand[] }> };
  skill: { list: () => Promise<{ data: RawSkill[] }> };
  mcp: { list: () => Promise<{ data: RawMcpServer[] }> };
  config: { get: () => Promise<RawConfigEntry[]> };
}

export interface ConnectionServiceOptions {
  dataDir: string;
  deploymentMode?: DeploymentMode;
  envBaseUrl?: string;
  envUsername?: string;
  envPassword?: string;
  clientFactory?: (options: NativeClientOptions) => NativeClientLike;
  now?: () => Date;
}

const settingsSchema = z.object({
  baseUrl: z.string().nullable().default(null),
  authMode: z.enum(["none", "basic"]).default("none"),
  username: z.string().default("opencode"),
  hasPassword: z.boolean().default(false),
  updatedAt: z.string().nullable().default(null),
});

type ConnectionSettings = z.infer<typeof settingsSchema>;

export interface CheckOptions {
  baseUrl?: string;
  username?: string;
  password?: string;
  selected?: ModelRef | null;
}

export interface ModelResolution {
  model: DiscoveredModel;
  source: "selected" | "legacy" | "auto-discovery";
}

export class ConnectionService {
  private settings: ConnectionSettings = settingsSchema.parse({});
  private password: string | undefined;
  private cached: ConnectionStatus;
  private discoveryCache: { discovery: OpenCodeDiscovery; expiresAt: number } | null = null;
  private readonly clientFactory: (options: NativeClientOptions) => NativeClientLike;
  private readonly now: () => Date;

  constructor(private readonly options: ConnectionServiceOptions) {
    this.clientFactory = options.clientFactory ?? ((clientOptions) => createNativeClient(clientOptions) as unknown as NativeClientLike);
    this.now = options.now ?? (() => new Date());
    this.password = REDACTED || undefined;
    this.cached = this.initialStatus();
  }

  get deploymentMode(): DeploymentMode {
    return this.options.deploymentMode ?? "local";
  }

  get managed(): boolean {
    return this.deploymentMode !== "local";
  }

  async load(): Promise<void> {
    let stored: Partial<ConnectionSettings> = {};
    try {
      stored = settingsSchema.parse(JSON.parse(await readFile(this.path, "utf8")));
    } catch {
      stored = {};
    }
    const envBase = this.options.envBaseUrl?.trim() || null;
    const baseUrl = stored.baseUrl ?? envBase;
    this.settings = settingsSchema.parse({
      baseUrl,
      authMode: stored.authMode ?? (this.password ? "basic" : "none"),
      username: stored.username ?? this.options.envUsername?.trim() ?? "opencode",
      hasPassword: stored.hasPassword ?? Boolean(this.password),
      updatedAt: stored.updatedAt ?? null,
    });
    this.cached = this.initialStatus();
  }

  get path(): string {
    return resolve(this.options.dataDir, "connection.json");
  }

  initialStatus(): ConnectionStatus {
    const baseUrl = this.settings.baseUrl ?? this.options.envBaseUrl?.trim() ?? null;
    return connectionStatusSchema.parse({
      state: baseUrl ? "not_configured" : "not_configured",
      baseUrl,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password) || this.settings.hasPassword,
      },
      serverVersion: null,
      compatible: null,
      checkedAt: null,
      diagnostics: [],
      discovery: null,
    });
  }

  status(): ConnectionStatus {
    return this.cached;
  }

  async refresh(options: { selected?: ModelRef | null } = {}): Promise<ConnectionStatus> {
    return this.check(options);
  }

  async configure(input: { baseUrl: string; username?: string; password?: string }): Promise<ConnectionStatus> {
    if (this.managed) {
      throw new ConnectionConfigError("This deployment manages the OpenCode connection through its environment and secret store.", "INVALID_URL");
    }
    const validated = validateServerUrl(input.baseUrl);
    const password = input.password === undefined ? this.password : input.password;
    this.password = REDACTED || undefined;
    this.settings = settingsSchema.parse({
      baseUrl: validated.url,
      authMode: this.password ? "basic" : "none",
      username: input.username?.trim() || this.settings.username || "opencode",
      hasPassword: Boolean(this.password),
      updatedAt: this.now().toISOString(),
    });
    await this.persist();
    this.discoveryCache = null;
    this.cached = this.initialStatus();
    return this.check({ baseUrl: validated.url, username: this.settings.username, selected: null });
  }

  async check(options: CheckOptions = {}): Promise<ConnectionStatus> {
    const baseUrlInput = options.baseUrl ?? this.settings.baseUrl ?? this.options.envBaseUrl ?? null;
    if (!baseUrlInput) {
      this.cached = this.initialStatus();
      return this.cached;
    }
    let validated;
    try {
      validated = validateServerUrl(baseUrlInput);
    } catch (error) {
      this.cached = this.failureStatus(baseUrlInput, error instanceof Error ? error.message : "Invalid server URL.", [
        {
          code: "INVALID_SERVER_URL",
          severity: "error",
          title: "Invalid OpenCode URL",
          message: error instanceof Error ? error.message : "The URL is invalid.",
          repair: "Use http://127.0.0.1:4096 for local OpenCode, or an https:// URL for a remote server.",
        },
      ]);
      return this.cached;
    }

    const username = options.username?.trim() || this.settings.username || "opencode";
    const password = options.password === undefined ? this.password : options.password.trim();
    const client = this.clientFactory({ baseUrl: validated.url, username, password });

    let info: { version: string };
    try {
      info = await client.server.info();
    } catch (error) {
      const failure = classifyConnectionError(error);
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: failure.code,
        severity: "error",
        title: failure.state === "authentication_required" ? "OpenCode authentication failed" : "OpenCode is not reachable",
        message: failure.message,
        repair: this.repairFor(failure.code),
      }], failure.state);
      this.settings = { ...this.settings, baseUrl: validated.url, username, authMode: password ? "basic" : "none" };
      return this.cached;
    }

    const compatibility = checkVersionCompatibility(info.version);
    if (!compatibility.compatible) {
      this.cached = connectionStatusSchema.parse({
        ...this.initialStatus(),
        state: "incompatible_version",
        baseUrl: validated.url,
        serverVersion: info.version,
        compatible: false,
        checkedAt: this.now().toISOString(),
        diagnostics: [{
          code: "UNSUPPORTED_SERVER_VERSION",
          severity: "error",
          title: "Unsupported OpenCode server version",
          message: compatibility.warning,
          repair: `Install OpenCode ${compatibility.major ?? "2"}.x compatible with @opencode/client 2.0.32, or update Unfinished Business.`,
        }],
      });
      return this.cached;
    }

    const [modelsResult, providersResult, integrationsResult, agentsResult, permissionsResult, commandsResult, skillsResult, mcpResult, configResult] = await Promise.allSettled([
      client.model.list(),
      client.provider.list(),
      client.integration.list(),
      client.agent.list(),
      client.permission.request.list(),
      client.command.list(),
      client.skill.list(),
      client.mcp.list(),
      client.config.get(),
    ]);

    if (modelsResult.status === "rejected" || providersResult.status === "rejected") {
      const failure = classifyConnectionError(modelsResult.status === "rejected" ? modelsResult.reason : providersResult.status === "rejected" ? providersResult.reason : undefined);
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: failure.code,
        severity: "error",
        title: "OpenCode discovery failed",
        message: failure.message,
        repair: "Confirm the server is healthy and that the account/project can list models. Then retry.",
      }], failure.state);
      return this.cached;
    }

    const raw: RawDiscoveryInput = {
      version: info.version,
      models: modelsResult.value.data,
      providers: providersResult.value.data,
      integrations: integrationsResult.status === "fulfilled" ? integrationsResult.value.data : [],
      agents: agentsResult.status === "fulfilled" ? agentsResult.value.data : [],
      permissions: permissionsResult.status === "fulfilled" ? permissionsResult.value.data : [],
      commands: commandsResult.status === "fulfilled" ? commandsResult.value.data : [],
      skills: skillsResult.status === "fulfilled" ? skillsResult.value.data : [],
      mcpServers: mcpResult.status === "fulfilled" ? mcpResult.value.data : [],
      config: configResult.status === "fulfilled" ? configResult.value : [],
    };
    const discovery = normalizeDiscovery(raw);
    discovery.limitations.push(...this.partialLimitations({
      integrations: integrationsResult.status,
      agents: agentsResult.status,
      permissions: permissionsResult.status,
      commands: commandsResult.status,
      skills: skillsResult.status,
      mcp: mcpResult.status,
      config: configResult.status,
    }));

    const diagnostics = this.diagnosticsFor(discovery, options.selected ?? null);
    const state = diagnostics.some((diagnostic) => diagnostic.severity === "error")
      ? "degraded"
      : diagnosticWarnings(diagnostics) || discovery.server.warning
        ? "degraded"
        : "connected";

    this.discoveryCache = { discovery, expiresAt: Date.now() + 30_000 };
    this.settings = {
      ...this.settings,
      baseUrl: validated.url,
      username,
      authMode: password ? "basic" : "none",
      hasPassword: Boolean(password) || this.settings.hasPassword,
      updatedAt: this.now().toISOString(),
    };
    this.password = password || undefined;
    if (!this.managed) await this.persist();
    this.cached = connectionStatusSchema.parse({
      state,
      baseUrl: validated.url,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password),
      },
      serverVersion: info.version,
      compatible: true,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery,
    });
    return this.cached;
  }

  async discovery(options: { selected?: ModelRef | null } = {}): Promise<OpenCodeDiscovery> {
    if (this.discoveryCache && this.discoveryCache.expiresAt > Date.now()) return this.discoveryCache.discovery;
    const status = await this.check({ selected: options.selected });
    if (!status.discovery) throw new Error("OpenCode discovery is unavailable until the connection succeeds.");
    return status.discovery;
  }

  async resolveModel(selection: ModelRef | null, discovery?: OpenCodeDiscovery): Promise<ModelResolution | null> {
    const current = discovery ?? await this.discovery({ selected: selection });
    if (selection) {
      const match = current.models.find((model) =>
        model.providerID === selection.providerID
        && model.id === selection.id
        && model.availability === "available",
      );
      if (match) {
        if (selection.variant && !match.variants.includes(selection.variant)) {
          throw new Error(`Variant "${selection.variant}" is not reported for ${match.key}.`);
        }
        return { model: match, source: "selected" };
      }
    }
    return null;
  }

  /** Pick a safe model for a project without inventing an unavailable identity. */
  async chooseDefaultModel(legacyModel?: string | null): Promise<ModelResolution | null> {
    const discovery = await this.discovery({ selected: null });
    const available = discovery.models.filter((model) => model.availability === "available");
    if (legacyModel) {
      const legacy = available.find((model) => model.key === legacyModel);
      if (legacy) return { model: legacy, source: "legacy" };
    }
    const preferred = available.find((model) => model.pricing === "free" && model.tools)
      ?? available.find((model) => model.tools)
      ?? available[0];
    return preferred ? { model: preferred, source: "auto-discovery" } : null;
  }

  validateSelection(discovery: OpenCodeDiscovery, model: ModelRef): DiscoveredModel {
    const match = discovery.models.find((candidate) =>
      candidate.providerID === model.providerID
      && candidate.id === model.id
      && candidate.availability === "available",
    );
    if (!match) throw new Error(`${model.providerID}/${model.id} is not an available model reported by OpenCode.`);
    if (model.variant && !match.variants.includes(model.variant)) {
      throw new Error(`Variant "${model.variant}" is not reported for ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`);
    }
    return match;
  }

  private async persist(): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    const temporary = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    await writeFile(temporary, `${JSON.stringify(this.settings, null, 2)}\n`, { mode: 0o600 });
    await chmod(temporary, 0o600);
    await rename(temporary, this.path);
  }

  private failureStatus(
    baseUrl: string,
    message: string,
    diagnostics: ConnectionStatus["diagnostics"],
    state: ConnectionStatus["state"] = "unavailable",
  ): ConnectionStatus {
    return connectionStatusSchema.parse({
      ...this.initialStatus(),
      state,
      baseUrl,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery: null,
      serverVersion: null,
      compatible: null,
    });
  }

  private repairFor(code: string): string {
    if (code === "AUTH_REQUIRED") return "Enter the OpenCode server password (the value printed by `opencode serve`, or OPENCODE_PASSWORD). Provider API keys belong in OpenCode, not here.";
    if (code === "ORIGIN_BLOCKED") return "Check the OpenCode server's hostname, CORS/origin settings, and reverse proxy. This application connects from the server, not the browser.";
    if (code === "TIMEOUT") return "Confirm the OpenCode process is healthy and the URL points at its API port. Retry when it is idle.";
    if (code === "MALFORMED") return "Confirm the URL points at an OpenCode 2.x server (not a different service or a stale proxy).";
    return "Start OpenCode with `opencode serve --hostname 127.0.0.1 --port 4096`, confirm the URL and port, then retry.";
  }

  private diagnosticsFor(discovery: OpenCodeDiscovery, selected: ModelRef | null) {
    const diagnostics: ConnectionStatus["diagnostics"] = [];
    if (discovery.server.warning) {
      diagnostics.push({
        code: "VERSION_UNTESTED",
        severity: "warning",
        title: "Untested OpenCode patch version",
        message: discovery.server.warning,
        repair: `Use OpenCode ${discovery.server.testedVersion} for the tested surface, or verify the new version with the live diagnostic.`,
      });
    }
    if (discovery.models.length === 0) {
      diagnostics.push({
        code: "NO_MODELS",
        severity: "error",
        title: "No models reported",
        message: "OpenCode returned no selectable models.",
        repair: "Connect a provider inside OpenCode (`/connect`), then run `/models` or restart the server. This app never asks for provider API keys.",
      });
    }
    const availableModels = discovery.models.filter((model) => model.availability === "available");
    if (discovery.models.length > 0 && availableModels.length === 0) {
      diagnostics.push({
        code: "NO_AVAILABLE_MODELS",
        severity: "error",
        title: "No available models",
        message: "Every model in the catalog is disabled or tied to a disabled provider.",
        repair: "Enable a provider/model inside OpenCode, then retry discovery.",
      });
    }
    for (const provider of discovery.providers.filter((item) => item.ready === "needs_auth")) {
      diagnostics.push({
        code: "PROVIDER_NOT_CONNECTED",
        severity: "warning",
        title: `${provider.name} needs authentication`,
        message: provider.detail,
        repair: `Connect ${provider.name} inside OpenCode with /connect, or choose a model from a provider that is already available.`,
      });
    }
    if (selected) {
      const match = discovery.models.find((model) => model.providerID === selected.providerID && model.id === selected.id);
      if (!match) {
        diagnostics.push({
          code: "MODEL_UNAVAILABLE",
          severity: "error",
          title: "Selected model is unavailable",
          message: `${selected.providerID}/${selected.id} is not in the current OpenCode catalog.`,
          repair: "Choose another model in the OpenCode panel. The previous selection was not replaced automatically.",
        });
      } else if (match.availability !== "available") {
        diagnostics.push({
          code: "MODEL_DISABLED",
          severity: "error",
          title: "Selected model is disabled",
          message: `${match.name} is present but unavailable (${match.status}).`,
          repair: "Enable the model or provider inside OpenCode, or choose another model.",
        });
      } else if (selected.variant && !match.variants.includes(selected.variant)) {
        diagnostics.push({
          code: "VARIANT_UNAVAILABLE",
          severity: "error",
          title: "Selected variant is not reported",
          message: `Variant "${selected.variant}" is not attached to ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`,
          repair: "Choose a variant reported for this model, or use the model default.",
        });
      }
      if (match?.local && ((match.limits.context ?? 0) < 8_192 || (match.limits.output ?? 0) < 1_024)) {
        diagnostics.push({
          code: "LOCAL_MODEL_LIMITS",
          severity: "warning",
          title: "Local model has small limits",
          message: `${match.name} reports a ${match.limits.context ?? "unknown"} token context and ${match.limits.output ?? "unknown"} token output limit.`,
          repair: "Lower the planned scope, increase the local model context/output in its runtime, or choose a model with larger limits. OpenCode does not report free RAM or VRAM.",
        });
      }
    }
    if (discovery.permissions.length > 0) {
      diagnostics.push({
        code: "PERMISSION_PENDING",
        severity: "warning",
        title: "Permission decisions are waiting",
        message: `${discovery.permissions.length} OpenCode permission request(s) need a human decision.`,
        repair: "Review each request in the OpenCode panel. This application never auto-approves a request.",
      });
    }
    return diagnostics;
  }

  private partialLimitations(results: Record<string, PromiseSettledResult<unknown> | "fulfilled" | "rejected">): string[] {
    const limitations: string[] = [];
    for (const [name, result] of Object.entries(results)) {
      const status = typeof result === "string" ? result : result.status;
      if (status === "rejected") limitations.push(`OpenCode ${name} discovery failed for this version. That section is visibly deferred.`);
    }
    return limitations;
  }
}

function diagnosticWarnings(diagnostics: ConnectionStatus["diagnostics"]): boolean {
  return diagnostics.some((diagnostic) => diagnostic.severity === "warning");
}

export function safeErrorMessage(error: unknown): string {
  return redactSecrets(error instanceof Error ? error.message : String(error));
}

import { chmod, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { z } from "zod";
import {
  connectionStatusSchema,
  type ConnectionStatus,
  type DeploymentMode,
  type DiscoveredModel,
  type OpenCodeDiscovery,
} from "../../shared/opencode.ts";
import type { ModelRef } from "../workflow/model.ts";
import {
  checkVersionCompatibility,
  classifyConnectionError,
  ConnectionConfigError,
  createNativeClient,
  redactSecrets,
  validateServerUrl,
  type NativeClientOptions,
} from "./client.ts";
import {
  normalizeDiscovery,
  type RawAgent,
  type RawCommand,
  type RawConfigEntry,
  type RawDiscoveryInput,
  type RawIntegration,
  type RawMcpServer,
  type RawModel,
  type RawPermissionRequest,
  type RawProvider,
  type RawSkill,
} from "./discovery.ts";

export interface NativeClientLike {
  server: { info: () => Promise<{ version: string }> };
  model: { list: () => Promise<{ data: RawModel[] }> };
  provider: { list: () => Promise<{ data: RawProvider[] }> };
  integration: { list: () => Promise<{ data: RawIntegration[] }> };
  agent: { list: () => Promise<{ data: RawAgent[] }> };
  permission: { request: { list: () => Promise<{ data: RawPermissionRequest[] }> } };
  command: { list: () => Promise<{ data: RawCommand[] }> };
  skill: { list: () => Promise<{ data: RawSkill[] }> };
  mcp: { list: () => Promise<{ data: RawMcpServer[] }> };
  config: { get: () => Promise<RawConfigEntry[]> };
}

export interface ConnectionServiceOptions {
  dataDir: string;
  deploymentMode?: DeploymentMode;
  envBaseUrl?: string;
  envUsername?: string;
  envPassword?: string;
  clientFactory?: (options: NativeClientOptions) => NativeClientLike;
  now?: () => Date;
}

const settingsSchema = z.object({
  baseUrl: z.string().nullable().default(null),
  authMode: z.enum(["none", "basic"]).default("none"),
  username: z.string().default("opencode"),
  hasPassword: z.boolean().default(false),
  updatedAt: z.string().nullable().default(null),
});

type ConnectionSettings = z.infer<typeof settingsSchema>;

export interface CheckOptions {
  baseUrl?: string;
  username?: string;
  password?: string;
  selected?: ModelRef | null;
}

export interface ModelResolution {
  model: DiscoveredModel;
  source: "selected" | "legacy" | "auto-discovery";
}

export class ConnectionService {
  private settings: ConnectionSettings = settingsSchema.parse({});
  private password: string | undefined;
  private cached: ConnectionStatus;
  private discoveryCache: { discovery: OpenCodeDiscovery; expiresAt: number } | null = null;
  private readonly clientFactory: (options: NativeClientOptions) => NativeClientLike;
  private readonly now: () => Date;

  constructor(private readonly options: ConnectionServiceOptions) {
    this.clientFactory = options.clientFactory ?? ((clientOptions) => createNativeClient(clientOptions) as unknown as NativeClientLike);
    this.now = options.now ?? (() => new Date());
    this.password = REDACTED || undefined;
    this.cached = this.initialStatus();
  }

  get deploymentMode(): DeploymentMode {
    return this.options.deploymentMode ?? "local";
  }

  get managed(): boolean {
    return this.deploymentMode !== "local";
  }

  async load(): Promise<void> {
    let stored: Partial<ConnectionSettings> = {};
    try {
      stored = settingsSchema.parse(JSON.parse(await readFile(this.path, "utf8")));
    } catch {
      stored = {};
    }
    const envBase = this.options.envBaseUrl?.trim() || null;
    const baseUrl = stored.baseUrl ?? envBase;
    this.settings = settingsSchema.parse({
      baseUrl,
      authMode: stored.authMode ?? (this.password ? "basic" : "none"),
      username: stored.username ?? this.options.envUsername?.trim() ?? "opencode",
      hasPassword: stored.hasPassword ?? Boolean(this.password),
      updatedAt: stored.updatedAt ?? null,
    });
    this.cached = this.initialStatus();
  }

  get path(): string {
    return resolve(this.options.dataDir, "connection.json");
  }

  initialStatus(): ConnectionStatus {
    const baseUrl = this.settings.baseUrl ?? this.options.envBaseUrl?.trim() ?? null;
    return connectionStatusSchema.parse({
      state: baseUrl ? "not_configured" : "not_configured",
      baseUrl,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password) || this.settings.hasPassword,
      },
      serverVersion: null,
      compatible: null,
      checkedAt: null,
      diagnostics: [],
      discovery: null,
    });
  }

  status(): ConnectionStatus {
    return this.cached;
  }

  async refresh(options: { selected?: ModelRef | null } = {}): Promise<ConnectionStatus> {
    return this.check(options);
  }

  async configure(input: { baseUrl: string; username?: string; password?: string }): Promise<ConnectionStatus> {
    if (this.managed) {
      throw new ConnectionConfigError("This deployment manages the OpenCode connection through its environment and secret store.", "INVALID_URL");
    }
    const validated = validateServerUrl(input.baseUrl);
    const password = input.password === undefined ? this.password : input.password;
    this.password = REDACTED || undefined;
    this.settings = settingsSchema.parse({
      baseUrl: validated.url,
      authMode: this.password ? "basic" : "none",
      username: input.username?.trim() || this.settings.username || "opencode",
      hasPassword: Boolean(this.password),
      updatedAt: this.now().toISOString(),
    });
    await this.persist();
    this.discoveryCache = null;
    this.cached = this.initialStatus();
    return this.check({ baseUrl: validated.url, username: this.settings.username, selected: null });
  }

  async check(options: CheckOptions = {}): Promise<ConnectionStatus> {
    const baseUrlInput = options.baseUrl ?? this.settings.baseUrl ?? this.options.envBaseUrl ?? null;
    if (!baseUrlInput) {
      this.cached = this.initialStatus();
      return this.cached;
    }
    let validated;
    try {
      validated = validateServerUrl(baseUrlInput);
    } catch (error) {
      this.cached = this.failureStatus(baseUrlInput, error instanceof Error ? error.message : "Invalid server URL.", [
        {
          code: "INVALID_SERVER_URL",
          severity: "error",
          title: "Invalid OpenCode URL",
          message: error instanceof Error ? error.message : "The URL is invalid.",
          repair: "Use http://127.0.0.1:4096 for local OpenCode, or an https:// URL for a remote server.",
        },
      ]);
      return this.cached;
    }

    const username = options.username?.trim() || this.settings.username || "opencode";
    const password = options.password === undefined ? this.password : options.password.trim();
    const client = this.clientFactory({ baseUrl: validated.url, username, password });

    let info: { version: string };
    try {
      info = await client.server.info();
    } catch (error) {
      const failure = classifyConnectionError(error);
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: failure.code,
        severity: "error",
        title: failure.state === "authentication_required" ? "OpenCode authentication failed" : "OpenCode is not reachable",
        message: failure.message,
        repair: this.repairFor(failure.code),
      }], failure.state);
      this.settings = { ...this.settings, baseUrl: validated.url, username, authMode: password ? "basic" : "none" };
      return this.cached;
    }

    const compatibility = checkVersionCompatibility(info.version);
    if (!compatibility.compatible) {
      this.cached = connectionStatusSchema.parse({
        ...this.initialStatus(),
        state: "incompatible_version",
        baseUrl: validated.url,
        serverVersion: info.version,
        compatible: false,
        checkedAt: this.now().toISOString(),
        diagnostics: [{
          code: "UNSUPPORTED_SERVER_VERSION",
          severity: "error",
          title: "Unsupported OpenCode server version",
          message: compatibility.warning,
          repair: `Install OpenCode ${compatibility.major ?? "2"}.x compatible with @opencode/client 2.0.32, or update Unfinished Business.`,
        }],
      });
      return this.cached;
    }

    const [modelsResult, providersResult, integrationsResult, agentsResult, permissionsResult, commandsResult, skillsResult, mcpResult, configResult] = await Promise.allSettled([
      client.model.list(),
      client.provider.list(),
      client.integration.list(),
      client.agent.list(),
      client.permission.request.list(),
      client.command.list(),
      client.skill.list(),
      client.mcp.list(),
      client.config.get(),
    ]);

    if (modelsResult.status === "rejected" || providersResult.status === "rejected") {
      const failure = classifyConnectionError(modelsResult.status === "rejected" ? modelsResult.reason : providersResult.status === "rejected" ? providersResult.reason : undefined);
      this.cached = this.failureStatus(validated.url, failure.message, [{
        code: failure.code,
        severity: "error",
        title: "OpenCode discovery failed",
        message: failure.message,
        repair: "Confirm the server is healthy and that the account/project can list models. Then retry.",
      }], failure.state);
      return this.cached;
    }

    const raw: RawDiscoveryInput = {
      version: info.version,
      models: modelsResult.value.data,
      providers: providersResult.value.data,
      integrations: integrationsResult.status === "fulfilled" ? integrationsResult.value.data : [],
      agents: agentsResult.status === "fulfilled" ? agentsResult.value.data : [],
      permissions: permissionsResult.status === "fulfilled" ? permissionsResult.value.data : [],
      commands: commandsResult.status === "fulfilled" ? commandsResult.value.data : [],
      skills: skillsResult.status === "fulfilled" ? skillsResult.value.data : [],
      mcpServers: mcpResult.status === "fulfilled" ? mcpResult.value.data : [],
      config: configResult.status === "fulfilled" ? configResult.value : [],
    };
    const discovery = normalizeDiscovery(raw);
    discovery.limitations.push(...this.partialLimitations({
      integrations: integrationsResult.status,
      agents: agentsResult.status,
      permissions: permissionsResult.status,
      commands: commandsResult.status,
      skills: skillsResult.status,
      mcp: mcpResult.status,
      config: configResult.status,
    }));

    const diagnostics = this.diagnosticsFor(discovery, options.selected ?? null);
    const state = diagnostics.some((diagnostic) => diagnostic.severity === "error")
      ? "degraded"
      : diagnosticWarnings(diagnostics) || discovery.server.warning
        ? "degraded"
        : "connected";

    this.discoveryCache = { discovery, expiresAt: Date.now() + 30_000 };
    this.settings = {
      ...this.settings,
      baseUrl: validated.url,
      username,
      authMode: password ? "basic" : "none",
      hasPassword: Boolean(password) || this.settings.hasPassword,
      updatedAt: this.now().toISOString(),
    };
    this.password = password || undefined;
    if (!this.managed) await this.persist();
    this.cached = connectionStatusSchema.parse({
      state,
      baseUrl: validated.url,
      deploymentMode: this.deploymentMode,
      managed: this.managed,
      auth: {
        mode: this.settings.authMode,
        username: this.settings.username,
        hasPassword: Boolean(this.password),
      },
      serverVersion: info.version,
      compatible: true,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery,
    });
    return this.cached;
  }

  async discovery(options: { selected?: ModelRef | null } = {}): Promise<OpenCodeDiscovery> {
    if (this.discoveryCache && this.discoveryCache.expiresAt > Date.now()) return this.discoveryCache.discovery;
    const status = await this.check({ selected: options.selected });
    if (!status.discovery) throw new Error("OpenCode discovery is unavailable until the connection succeeds.");
    return status.discovery;
  }

  async resolveModel(selection: ModelRef | null, discovery?: OpenCodeDiscovery): Promise<ModelResolution | null> {
    const current = discovery ?? await this.discovery({ selected: selection });
    if (selection) {
      const match = current.models.find((model) =>
        model.providerID === selection.providerID
        && model.id === selection.id
        && model.availability === "available",
      );
      if (match) {
        if (selection.variant && !match.variants.includes(selection.variant)) {
          throw new Error(`Variant "${selection.variant}" is not reported for ${match.key}.`);
        }
        return { model: match, source: "selected" };
      }
    }
    return null;
  }

  /** Pick a safe model for a project without inventing an unavailable identity. */
  async chooseDefaultModel(legacyModel?: string | null): Promise<ModelResolution | null> {
    const discovery = await this.discovery({ selected: null });
    const available = discovery.models.filter((model) => model.availability === "available");
    if (legacyModel) {
      const legacy = available.find((model) => model.key === legacyModel);
      if (legacy) return { model: legacy, source: "legacy" };
    }
    const preferred = available.find((model) => model.pricing === "free" && model.tools)
      ?? available.find((model) => model.tools)
      ?? available[0];
    return preferred ? { model: preferred, source: "auto-discovery" } : null;
  }

  validateSelection(discovery: OpenCodeDiscovery, model: ModelRef): DiscoveredModel {
    const match = discovery.models.find((candidate) =>
      candidate.providerID === model.providerID
      && candidate.id === model.id
      && candidate.availability === "available",
    );
    if (!match) throw new Error(`${model.providerID}/${model.id} is not an available model reported by OpenCode.`);
    if (model.variant && !match.variants.includes(model.variant)) {
      throw new Error(`Variant "${model.variant}" is not reported for ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`);
    }
    return match;
  }

  private async persist(): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    const temporary = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    await writeFile(temporary, `${JSON.stringify(this.settings, null, 2)}\n`, { mode: 0o600 });
    await chmod(temporary, 0o600);
    await rename(temporary, this.path);
  }

  private failureStatus(
    baseUrl: string,
    message: string,
    diagnostics: ConnectionStatus["diagnostics"],
    state: ConnectionStatus["state"] = "unavailable",
  ): ConnectionStatus {
    return connectionStatusSchema.parse({
      ...this.initialStatus(),
      state,
      baseUrl,
      checkedAt: this.now().toISOString(),
      diagnostics,
      discovery: null,
      serverVersion: null,
      compatible: null,
    });
  }

  private repairFor(code: string): string {
    if (code === "AUTH_REQUIRED") return "Enter the OpenCode server password (the value printed by `opencode serve`, or OPENCODE_PASSWORD). Provider API keys belong in OpenCode, not here.";
    if (code === "ORIGIN_BLOCKED") return "Check the OpenCode server's hostname, CORS/origin settings, and reverse proxy. This application connects from the server, not the browser.";
    if (code === "TIMEOUT") return "Confirm the OpenCode process is healthy and the URL points at its API port. Retry when it is idle.";
    if (code === "MALFORMED") return "Confirm the URL points at an OpenCode 2.x server (not a different service or a stale proxy).";
    return "Start OpenCode with `opencode serve --hostname 127.0.0.1 --port 4096`, confirm the URL and port, then retry.";
  }

  private diagnosticsFor(discovery: OpenCodeDiscovery, selected: ModelRef | null) {
    const diagnostics: ConnectionStatus["diagnostics"] = [];
    if (discovery.server.warning) {
      diagnostics.push({
        code: "VERSION_UNTESTED",
        severity: "warning",
        title: "Untested OpenCode patch version",
        message: discovery.server.warning,
        repair: `Use OpenCode ${discovery.server.testedVersion} for the tested surface, or verify the new version with the live diagnostic.`,
      });
    }
    if (discovery.models.length === 0) {
      diagnostics.push({
        code: "NO_MODELS",
        severity: "error",
        title: "No models reported",
        message: "OpenCode returned no selectable models.",
        repair: "Connect a provider inside OpenCode (`/connect`), then run `/models` or restart the server. This app never asks for provider API keys.",
      });
    }
    const availableModels = discovery.models.filter((model) => model.availability === "available");
    if (discovery.models.length > 0 && availableModels.length === 0) {
      diagnostics.push({
        code: "NO_AVAILABLE_MODELS",
        severity: "error",
        title: "No available models",
        message: "Every model in the catalog is disabled or tied to a disabled provider.",
        repair: "Enable a provider/model inside OpenCode, then retry discovery.",
      });
    }
    for (const provider of discovery.providers.filter((item) => item.ready === "needs_auth")) {
      diagnostics.push({
        code: "PROVIDER_NOT_CONNECTED",
        severity: "warning",
        title: `${provider.name} needs authentication`,
        message: provider.detail,
        repair: `Connect ${provider.name} inside OpenCode with /connect, or choose a model from a provider that is already available.`,
      });
    }
    if (selected) {
      const match = discovery.models.find((model) => model.providerID === selected.providerID && model.id === selected.id);
      if (!match) {
        diagnostics.push({
          code: "MODEL_UNAVAILABLE",
          severity: "error",
          title: "Selected model is unavailable",
          message: `${selected.providerID}/${selected.id} is not in the current OpenCode catalog.`,
          repair: "Choose another model in the OpenCode panel. The previous selection was not replaced automatically.",
        });
      } else if (match.availability !== "available") {
        diagnostics.push({
          code: "MODEL_DISABLED",
          severity: "error",
          title: "Selected model is disabled",
          message: `${match.name} is present but unavailable (${match.status}).`,
          repair: "Enable the model or provider inside OpenCode, or choose another model.",
        });
      } else if (selected.variant && !match.variants.includes(selected.variant)) {
        diagnostics.push({
          code: "VARIANT_UNAVAILABLE",
          severity: "error",
          title: "Selected variant is not reported",
          message: `Variant "${selected.variant}" is not attached to ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`,
          repair: "Choose a variant reported for this model, or use the model default.",
        });
      }
      if (match?.local && ((match.limits.context ?? 0) < 8_192 || (match.limits.output ?? 0) < 1_024)) {
        diagnostics.push({
          code: "LOCAL_MODEL_LIMITS",
          severity: "warning",
          title: "Local model has small limits",
          message: `${match.name} reports a ${match.limits.context ?? "unknown"} token context and ${match.limits.output ?? "unknown"} token output limit.`,
          repair: "Lower the planned scope, increase the local model context/output in its runtime, or choose a model with larger limits. OpenCode does not report free RAM or VRAM.",
        });
      }
    }
    if (discovery.permissions.length > 0) {
      diagnostics.push({
        code: "PERMISSION_PENDING",
        severity: "warning",
        title: "Permission decisions are waiting",
        message: `${discovery.permissions.length} OpenCode permission request(s) need a human decision.`,
        repair: "Review each request in the OpenCode panel. This application never auto-approves a request.",
      });
    }
    return diagnostics;
  }

  private partialLimitations(results: Record<string, PromiseSettledResult<unknown> | "fulfilled" | "rejected">): string[] {
    const limitations: string[] = [];
    for (const [name, result] of Object.entries(results)) {
      const status = typeof result === "string" ? result : result.status;
      if (status === "rejected") limitations.push(`OpenCode ${name} discovery failed for this version. That section is visibly deferred.`);
    }
    return limitations;
  }
}

function diagnosticWarnings(diagnostics: ConnectionStatus["diagnostics"]): boolean {
  return diagnostics.some((diagnostic) => diagnostic.severity === "warning");
}

export function safeErrorMessage(error: unknown): string {
  return redactSecrets(error instanceof Error ? error.message : String(error));
}

import type { ModelRef } from "../workflow/model.ts";
import { createNativeClient, type NativeClientOptions } from "../opencode/client.ts";
import {
  setOpenCodeResult,
  traceChatOperation,
  traceCreateAgent,
  traceToolOperation,
} from "./telemetry.ts";

export interface SpokenResult {
  sessionId: string;
  messageId: string | null;
  text: string;
  cost: number;
}

export interface PerformedResult extends SpokenResult {
  diff: string;
}

export interface SessionContext {
  conversationId: string;
  sessionId: string | null;
  prompt: string;
  workspace: string;
  model: ModelRef;
  agent: string | null;
  onSession?: (sessionId: string) => void;
}

export interface SpiritGuide {
  speak(input: SessionContext & { role: "oracle" | "architect" | "witness" }): Promise<SpokenResult>;
  perform(input: SessionContext & { role: "maker" }): Promise<PerformedResult>;
  inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown">;
  interrupt(sessionId: string): Promise<boolean>;
}

const readOnlyPermissions = [
  { action: "edit", resource: "*", effect: "deny" as const },
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
];

const makerPermissions = [
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
  { action: "edit", resource: "*", effect: "allow" as const },
];

function assertSelectedModel(
  selected: ModelRef,
  actual: { providerID: string; id: string; variant?: string } | undefined,
): void {
  if (!actual) return;
  if (actual.providerID !== selected.providerID || actual.id !== selected.id) {
    throw new Error(`Native session left the selected model ${selected.providerID}/${selected.id}.`);
  }
  // OpenCode reports "default" when no explicit variant was selected. A user
  // variant must still be the one this application requested.
  if (selected.variant && actual.variant && actual.variant !== "default" && actual.variant !== selected.variant) {
    throw new Error(`Native session left the selected variant "${selected.variant}".`);
  }
}

export class OpenCodeSpiritGuide implements SpiritGuide {
  constructor(private readonly options: NativeClientOptions) {}

  private client() {
    return createNativeClient(this.options);
  }

  private async openSession(
    role: "oracle" | "architect" | "maker" | "witness",
    input: SessionContext,
    permissions: Array<{ action: string; resource: string; effect: "allow" | "deny" | "ask" }>,
  ) {
    if (input.sessionId) {
      input.onSession?.(input.sessionId);
      return input.sessionId;
    }
    return traceCreateAgent(role, input.conversationId, async (span) => {
      const created = await this.client().session.create({
        title: `Unfinished Business ${role}`,
        agent: input.agent ?? undefined,
        model: {
          providerID: input.model.providerID,
          id: input.model.id,
          ...(input.model.variant ? { variant: input.model.variant } : {}),
        },
        location: { directory: input.workspace },
        permissions,
      });
      setOpenCodeResult(span, { sessionId: created.id, model: input.model });
      input.onSession?.(created.id);
      return created.id;
    });
  }

  async speak(input: SessionContext & { role: "oracle" | "architect" | "witness" }): Promise<SpokenResult> {
    return traceChatOperation(input.role, input.conversationId, input.model, async (span) => {
      const sessionId = await this.openSession(input.role, input, readOnlyPermissions);
      const generated = await this.client().session.generate({ sessionID: sessionId, prompt: input.prompt });
      let text = generated.text?.trim() ?? "";
      if (text.length < 80) {
        await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
        await Promise.race([
          this.client().session.wait({ sessionID: sessionId }),
          new Promise<never>((_, reject) => {
            setTimeout(() => reject(new Error("Native spirit timed out before it became idle.")), 90_000);
          }),
        ]);
        const listed = await this.client().message.list({ sessionID: sessionId, type: "assistant" });
        const messages = Array.isArray(listed) ? listed : listed.data;
        text = messages.flatMap((message) => message.type === "assistant" ? message.content : [])
          .flatMap((part) => part.type === "text" ? [part.text] : [])
          .join("\n")
          .trim();
      }
      const info = await this.client().session.get({ sessionID: sessionId });
      assertSelectedModel(input.model, info.model);
      if (!text) throw new Error("Native session returned no assistant text.");
      setOpenCodeResult(span, { sessionId, cost: info.cost, model: input.model });
      return { sessionId, messageId: null, text, cost: info.cost };
    });
  }

  async perform(input: SessionContext & { role: "maker" }): Promise<PerformedResult> {
    return traceChatOperation("maker", input.conversationId, input.model, async (span) => {
      const sessionId = await this.openSession("maker", input, makerPermissions);
      const prompted = await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
      let timedOut = false;
      await Promise.race([
        this.client().session.wait({ sessionID: sessionId }),
        new Promise<void>((resolve) => {
          setTimeout(() => {
            timedOut = true;
            resolve();
          }, 180_000);
        }),
      ]);
      const info = await this.client().session.get({ sessionID: sessionId });
      assertSelectedModel(input.model, info.model);
      const diff = await traceToolOperation("maker", input.conversationId, input.model, "opencode.session.diff", async (toolSpan) => {
        const result = await this.client().session.diff({ sessionID: sessionId });
        setOpenCodeResult(toolSpan, { sessionId, model: input.model });
        toolSpan.setAttribute("opencode.diff.file_count", result.length);
        return result;
      });
      const summary = diff.length
        ? diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
        : timedOut
          ? "Native Maker run timed out before it became idle, without a file diff."
          : "Native session finished without a file diff.";
      const messageId = typeof prompted.id === "string" ? prompted.id : null;
      setOpenCodeResult(span, { sessionId, messageId, cost: info.cost, model: input.model });
      return { sessionId, messageId, text: summary, diff: summary, cost: info.cost };
    });
  }

  async inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown"> {
    return traceToolOperation(context.role, context.conversationId, null, "opencode.session.inspect", async (span) => {
      const info = await this.client().session.get({ sessionID: sessionId });
      setOpenCodeResult(span, { sessionId, cost: info.cost, model: null });
      if (info.outcome === "succeeded") return "succeeded";
      if (info.outcome === "failed" || info.outcome === "interrupted") return "failed";
      if (!info.time.idle) return "running";
      return "unknown";
    });
  }

  async interrupt(sessionId: string): Promise<boolean> {
    const result = await this.client().session.interrupt({ sessionID: sessionId });
    return Boolean(result.interrupted);
  }
}

import type { ModelRef } from "../workflow/model.ts";
import { createNativeClient, type NativeClientOptions } from "../opencode/client.ts";
import {
  setOpenCodeResult,
  traceChatOperation,
  traceCreateAgent,
  traceToolOperation,
} from "./telemetry.ts";

export interface SpokenResult {
  sessionId: string;
  messageId: string | null;
  text: string;
  cost: number;
}

export interface PerformedResult extends SpokenResult {
  diff: string;
}

export interface SessionContext {
  conversationId: string;
  sessionId: string | null;
  prompt: string;
  workspace: string;
  model: ModelRef;
  agent: string | null;
  onSession?: (sessionId: string) => void;
}

export interface SpiritGuide {
  speak(input: SessionContext & { role: "oracle" | "architect" | "witness" }): Promise<SpokenResult>;
  perform(input: SessionContext & { role: "maker" }): Promise<PerformedResult>;
  inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown">;
  interrupt(sessionId: string): Promise<boolean>;
}

const readOnlyPermissions = [
  { action: "edit", resource: "*", effect: "deny" as const },
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
];

const makerPermissions = [
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
  { action: "edit", resource: "*", effect: "allow" as const },
];

function assertSelectedModel(
  selected: ModelRef,
  actual: { providerID: string; id: string; variant?: string } | undefined,
): void {
  if (!actual) return;
  if (actual.providerID !== selected.providerID || actual.id !== selected.id) {
    throw new Error(`Native session left the selected model ${selected.providerID}/${selected.id}.`);
  }
  // OpenCode reports "default" when no explicit variant was selected. A user
  // variant must still be the one this application requested.
  if (selected.variant && actual.variant && actual.variant !== "default" && actual.variant !== selected.variant) {
    throw new Error(`Native session left the selected variant "${selected.variant}".`);
  }
}

export class OpenCodeSpiritGuide implements SpiritGuide {
  constructor(private readonly options: NativeClientOptions) {}

  private client() {
    return createNativeClient(this.options);
  }

  private async openSession(
    role: "oracle" | "architect" | "maker" | "witness",
    input: SessionContext,
    permissions: Array<{ action: string; resource: string; effect: "allow" | "deny" | "ask" }>,
  ) {
    if (input.sessionId) {
      input.onSession?.(input.sessionId);
      return input.sessionId;
    }
    return traceCreateAgent(role, input.conversationId, async (span) => {
      const created = await this.client().session.create({
        title: `Unfinished Business ${role}`,
        agent: input.agent ?? undefined,
        model: {
          providerID: input.model.providerID,
          id: input.model.id,
          ...(input.model.variant ? { variant: input.model.variant } : {}),
        },
        location: { directory: input.workspace },
        permissions,
      });
      setOpenCodeResult(span, { sessionId: created.id, model: input.model });
      input.onSession?.(created.id);
      return created.id;
    });
  }

  async speak(input: SessionContext & { role: "oracle" | "architect" | "witness" }): Promise<SpokenResult> {
    return traceChatOperation(input.role, input.conversationId, input.model, async (span) => {
      const sessionId = await this.openSession(input.role, input, readOnlyPermissions);
      const generated = await this.client().session.generate({ sessionID: sessionId, prompt: input.prompt });
      let text = generated.text?.trim() ?? "";
      if (text.length < 80) {
        await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
        await Promise.race([
          this.client().session.wait({ sessionID: sessionId }),
          new Promise<never>((_, reject) => {
            setTimeout(() => reject(new Error("Native spirit timed out before it became idle.")), 90_000);
          }),
        ]);
        const listed = await this.client().message.list({ sessionID: sessionId, type: "assistant" });
        const messages = Array.isArray(listed) ? listed : listed.data;
        text = messages.flatMap((message) => message.type === "assistant" ? message.content : [])
          .flatMap((part) => part.type === "text" ? [part.text] : [])
          .join("\n")
          .trim();
      }
      const info = await this.client().session.get({ sessionID: sessionId });
      assertSelectedModel(input.model, info.model);
      if (!text) throw new Error("Native session returned no assistant text.");
      setOpenCodeResult(span, { sessionId, cost: info.cost, model: input.model });
      return { sessionId, messageId: null, text, cost: info.cost };
    });
  }

  async perform(input: SessionContext & { role: "maker" }): Promise<PerformedResult> {
    return traceChatOperation("maker", input.conversationId, input.model, async (span) => {
      const sessionId = await this.openSession("maker", input, makerPermissions);
      const prompted = await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
      let timedOut = false;
      await Promise.race([
        this.client().session.wait({ sessionID: sessionId }),
        new Promise<void>((resolve) => {
          setTimeout(() => {
            timedOut = true;
            resolve();
          }, 180_000);
        }),
      ]);
      const info = await this.client().session.get({ sessionID: sessionId });
      assertSelectedModel(input.model, info.model);
      const diff = await traceToolOperation("maker", input.conversationId, input.model, "opencode.session.diff", async (toolSpan) => {
        const result = await this.client().session.diff({ sessionID: sessionId });
        setOpenCodeResult(toolSpan, { sessionId, model: input.model });
        toolSpan.setAttribute("opencode.diff.file_count", result.length);
        return result;
      });
      const summary = diff.length
        ? diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
        : timedOut
          ? "Native Maker run timed out before it became idle, without a file diff."
          : "Native session finished without a file diff.";
      const messageId = typeof prompted.id === "string" ? prompted.id : null;
      setOpenCodeResult(span, { sessionId, messageId, cost: info.cost, model: input.model });
      return { sessionId, messageId, text: summary, diff: summary, cost: info.cost };
    });
  }

  async inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown"> {
    return traceToolOperation(context.role, context.conversationId, null, "opencode.session.inspect", async (span) => {
      const info = await this.client().session.get({ sessionID: sessionId });
      setOpenCodeResult(span, { sessionId, cost: info.cost, model: null });
      if (info.outcome === "succeeded") return "succeeded";
      if (info.outcome === "failed" || info.outcome === "interrupted") return "failed";
      if (!info.time.idle) return "running";
      return "unknown";
    });
  }

  async interrupt(sessionId: string): Promise<boolean> {
    const result = await this.client().session.interrupt({ sessionID: sessionId });
    return Boolean(result.interrupted);
  }
}

import * as Sentry from "@sentry/hono/node";
import type { Span } from "@sentry/hono/node";
import type { ModelRef } from "../workflow/model.ts";

type SpiritRole = "oracle" | "architect" | "maker" | "witness";

interface OpenCodeResultMetadata {
  sessionId?: string | null;
  messageId?: string | null;
  cost?: number;
  model?: ModelRef | null;
}

const pipelineName = "unfinished-business";
const providerName = "opencode";

function baseAttributes(role: SpiritRole, conversationId: string, model: ModelRef | null) {
  return {
    "gen_ai.agent.name": role,
    "gen_ai.conversation.id": conversationId,
    "gen_ai.pipeline.name": pipelineName,
    "gen_ai.provider.name": providerName,
    ...(model ? { "gen_ai.request.model": `${model.providerID}/${model.id}` } : {}),
  };
}

function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  if (/authentication|unauthori[sz]ed|password/i.test(message)) return "unauthenticated";
  return "internal_error";
}

function traced<T>(
  options: Parameters<typeof Sentry.startSpan<T>>[0],
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return Sentry.startSpan(options, async (span) => {
    try {
      const result = await work(span);
      span.setStatus({ code: 1 });
      return result;
    } catch (error) {
      span.setStatus({ code: 2, message: safeSpanError(error) });
      throw error;
    }
  });
}

export function traceAgentOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `invoke_agent ${role}`,
    op: "gen_ai.invoke_agent",
    attributes: {
      ...baseAttributes(role, conversationId, null),
      "gen_ai.operation.name": "invoke_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceChatOperation<T>(
  role: SpiritRole,
  conversationId: string,
  model: ModelRef | null,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  const modelName = model ? `${model.providerID}/${model.id}` : "unselected-model";
  return traced({
    name: `chat ${modelName}`,
    op: "gen_ai.chat",
    attributes: {
      ...baseAttributes(role, conversationId, model),
      "gen_ai.operation.name": "chat",
      "gen_ai.operation.type": "ai_client",
    },
  }, work);
}

export function traceCreateAgent<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `create_agent ${role}`,
    op: "gen_ai.create_agent",
    attributes: {
      ...baseAttributes(role, conversationId, null),
      "gen_ai.operation.name": "create_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceToolOperation<T>(
  role: SpiritRole,
  conversationId: string,
  model: ModelRef | null,
  toolName: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `execute_tool ${toolName}`,
    op: "gen_ai.execute_tool",
    attributes: {
      ...baseAttributes(role, conversationId, model),
      "gen_ai.operation.name": "execute_tool",
      "gen_ai.operation.type": "tool",
      "gen_ai.tool.name": toolName,
    },
  }, work);
}

export function setOpenCodeResult(span: Span, metadata: OpenCodeResultMetadata): void {
  if (metadata.model) span.setAttribute("gen_ai.response.model", `${metadata.model.providerID}/${metadata.model.id}`);
  if (metadata.sessionId) span.setAttribute("opencode.session.id", metadata.sessionId);
  if (metadata.messageId) span.setAttribute("gen_ai.response.id", metadata.messageId);
  if (typeof metadata.cost === "number" && Number.isFinite(metadata.cost)) {
    span.setAttribute("gen_ai.cost.total_tokens", metadata.cost);
  }
}

