import { useMemo, useState } from "react";
import { AlertTriangle, CheckCircle2, KeyRound, LockKeyhole, PlugZap, Server, Sparkles } from "lucide-react";
import type { ConnectionStatus, DiscoveredModel, OpenCodeDiscovery } from "../shared/opencode.ts";
import {
  ApiError,
  configureConnection,
  selectModel,
  type WorkshopProject,
} from "./api.ts";

export function formatTokens(value: number | null): string {
  if (value === null) return "not reported";
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `${Math.round(value / 1_000)}k`;
  return String(value);
}

export function modelLabel(model: DiscoveredModel): string {
  return `${model.name} — ${model.providerID}/${model.id}`;
}

function pricingLabel(model: DiscoveredModel): string {
  if (model.pricing === "free") return "Free";
  if (model.pricing === "paid") return "Paid";
  return "Price not reported";
}

function statusCopy(state: ConnectionStatus["state"]): { title: string; detail: string; tone: string } {
  switch (state) {
    case "connected":
      return { title: "OpenCode is connected", detail: "The server and catalog answered. No model call was made.", tone: "good" };
    case "degraded":
      return { title: "Connected with warnings", detail: "OpenCode answered, but some capability or provider checks need attention.", tone: "warn" };
    case "authentication_required":
      return { title: "Authentication required", detail: "OpenCode rejected the application connection. Enter the server password, not a provider API key.", tone: "bad" };
    case "incompatible_version":
      return { title: "Unsupported OpenCode version", detail: "This build is tested against the 2.x HTTP surface. Install a compatible server before continuing.", tone: "bad" };
    case "unavailable":
      return { title: "OpenCode is unavailable", detail: "The server did not answer. Start it and retry; nothing was inferred.", tone: "bad" };
    case "checking":
      return { title: "Checking OpenCode", detail: "A read-only connection and discovery check is running.", tone: "warn" };
    default:
      return { title: "Connect OpenCode", detail: "Point this workshop at a running OpenCode server. Provider credentials stay inside OpenCode.", tone: "warn" };
  }
}

export function Onboarding(props: {
  connection: ConnectionStatus;
  project: WorkshopProject;
  onConnection: (status: ConnectionStatus) => void;
  onProject: (project: WorkshopProject) => void;
  onClose?: () => void;
  firstRun: boolean;
}) {
  const selected = props.project.engine.model;
  const selectedModel = useMemo(
    () => props.connection.discovery?.models.find((model) => model.providerID === selected?.providerID && model.id === selected?.id) ?? null,
    [props.connection.discovery, selected],
  );
  const [phase, setPhase] = useState<"connect" | "model">(props.connection.discovery ? "model" : "connect");
  const [baseUrl, setBaseUrl] = useState(props.connection.baseUrl ?? "http://127.0.0.1:4096");
  const [username, setUsername] = useState(props.connection.auth.username || "opencode");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [chosenKey, setChosenKey] = useState(
    selected ? `${selected.providerID}/${selected.id}` : props.connection.discovery?.models.find((model) => model.availability === "available" && model.pricing === "free" && model.tools)?.key
      ?? props.connection.discovery?.models.find((model) => model.availability === "available")?.key
      ?? "",
  );
  const [variant, setVariant] = useState(selected?.variant ?? "");
  const copy = statusCopy(props.connection.state);
  const discovery = props.connection.discovery;
  const chosen = discovery?.models.find((model) => model.key === chosenKey) ?? null;

  async function connect() {
    setBusy(true);
    setError(null);
    try {
      const status = await configureConnection({
        baseUrl: baseUrl.trim(),
        username: username.trim() || "opencode",
        ...(password ? { password } : {}),
      });
      props.onConnection(status);
      if (status.discovery) {
        setPhase("model");
        const preferred = status.discovery.models.find((model) => model.availability === "available" && model.pricing === "free" && model.tools)
          ?? status.discovery.models.find((model) => model.availability === "available");
        if (preferred) {
          setChosenKey(preferred.key);
          setVariant("");
        }
      }
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : "The connection check failed.");
    } finally {
      setBusy(false);
    }
  }

  async function finish() {
    if (!chosen) return;
    setBusy(true);
    setError(null);
    try {
      const result = await selectModel(props.project, {
        providerID: chosen.providerID,
        id: chosen.id,
        variant: variant || null,
      });
      props.onProject(result.project);
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : "The model selection could not be saved.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="onboarding" aria-labelledby="onboarding-title">
      <div className="onboarding-head">
        <div>
          <p className="eyebrow">First run</p>
          <h1 id="onboarding-title">Connect your OpenCode workshop</h1>
          <p className="status-line">
            Start OpenCode yourself, then connect this app to it. Unfinished Business never asks for provider API keys and
            never stores them in the browser.
          </p>
        </div>
        {!props.firstRun && props.onClose ? (
          <button className="action secondary" type="button" onClick={props.onClose}>Close</button>
        ) : null}
      </div>

      <ol className="wizard-steps" aria-label="Setup steps">
        <li className={phase === "connect" ? "current" : "done"}><Server size={16} aria-hidden="true" /> Server</li>
        <li className={phase === "model" ? "current" : ""}><Sparkles size={16} aria-hidden="true" /> Model</li>
        <li><CheckCircle2 size={16} aria-hidden="true" /> Verify</li>
      </ol>

      {phase === "connect" ? (
        <div className="wizard-grid">
          <div className="wizard-card">
            <h2><PlugZap size={20} aria-hidden="true" /> 1. Start OpenCode</h2>
            <p>In a terminal on the machine that will run the workshop:</p>
            <pre className="command">opencode serve --hostname 127.0.0.1 --port 4096</pre>
            <p className="note">
              OpenCode prints a server password. The app uses it for its own Basic-auth connection. It is held in this
              process only and is never written to project JSON, browser storage, logs, or Sentry.
            </p>
            <p className="note">
              Provider accounts are connected inside OpenCode with <code>/connect</code>, then a model is chosen with
              <code>/models</code>. Those keys remain in OpenCode&apos;s credential store.
            </p>
            {props.connection.managed ? (
              <p className="banner">This deployment manages the URL and credentials through its environment and secret store. Retry the managed connection instead.</p>
            ) : null}
            <div className="wizard-actions">
              <button className="action" type="button" disabled={busy} onClick={() => void connect()}>
                {busy ? "Checking…" : props.connection.managed ? "Retry managed connection" : "Test connection"}
              </button>
            </div>
          </div>

          <div className="wizard-card">
            <h2><LockKeyhole size={20} aria-hidden="true" /> 2. Connection details</h2>
            <label>
              OpenCode server URL
              <input
                type="url"
                value={baseUrl}
                onChange={(event) => setBaseUrl(event.target.value)}
                placeholder="http://127.0.0.1:4096"
                disabled={props.connection.managed}
                autoComplete="off"
              />
            </label>
            <p className="note">Loopback HTTP is allowed locally. A remote server must use HTTPS. Credentials in the URL are rejected.</p>
            <label>
              Basic-auth username
              <input value={username} onChange={(event) => setUsername(event.target.value)} disabled={props.connection.managed} autoComplete="username" />
            </label>
            <label>
              OpenCode server password
              <input
                type="password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                placeholder={props.connection.auth.hasPassword ? "Password already held in this process" : "Paste the password printed by opencode serve"}
                disabled={props.connection.managed}
                autoComplete="current-password"
              />
            </label>
            <p className="note"><KeyRound size={14} aria-hidden="true" /> This is the OpenCode server password, not an OpenAI/Anthropic/etc. API key. Provider keys are rejected by this API.</p>
          </div>
        </div>
      ) : (
        <div className="wizard-card">
          <h2><Sparkles size={20} aria-hidden="true" /> 3. Choose a model</h2>
          {discovery ? <DiscoverySummary discovery={discovery} /> : null}
          <div className="model-list" role="radiogroup" aria-label="Available models">
            {(discovery?.models ?? []).filter((model) => model.availability === "available").map((model) => (
              <label key={model.key} className={model.key === chosenKey ? "model-option selected" : "model-option"}>
                <input
                  type="radio"
                  name="model"
                  value={model.key}
                  checked={model.key === chosenKey}
                  onChange={() => {
                    setChosenKey(model.key);
                    setVariant("");
                  }}
                />
                <span>
                  <strong>{model.name}</strong>
                  <span className="meta">{model.providerID}/{model.id}</span>
                  <span className="model-facts">
                    {pricingLabel(model)} · {formatTokens(model.limits.context)} context · {formatTokens(model.limits.output)} output ·{" "}
                    {model.tools ? "tools" : "no tools"} · {model.modalities.input.join("/")} input
                    {model.local ? " · local" : ""}
                  </span>
                  {model.reasoning.supported ? (
                    <span className="meta">Reasoning: {model.reasoning.source === "variants" ? "model-reported variants" : "provider compatibility"}</span>
                  ) : null}
                </span>
              </label>
            ))}
          </div>
          {chosen ? (
            <div className="model-detail">
              <p><strong>{modelLabel(chosen)}</strong></p>
              <p className="meta">
                {pricingLabel(chosen)} · context {formatTokens(chosen.limits.context)} · input {formatTokens(chosen.limits.input)} · output {formatTokens(chosen.limits.output)}
              </p>
              <label>
                Variant
                <select value={variant} onChange={(event) => setVariant(event.target.value)}>
                  <option value="">Model default</option>
                  {chosen.variants.map((id) => <option key={id} value={id}>{id}</option>)}
                </select>
              </label>
              <p className="note">Only variants reported for this model are listed. There is no universal low/medium/high scale.</p>
            </div>
          ) : (
            <p className="banner bad">No available model is reported. Connect a provider inside OpenCode, then retry discovery.</p>
          )}
          <div className="wizard-actions">
            <button className="action secondary" type="button" onClick={() => setPhase("connect")}>Back</button>
            <button className="action" type="button" disabled={!chosen || busy} onClick={() => void finish()}>
              {busy ? "Saving…" : "Use this model"}
            </button>
          </div>
        </div>
      )}

      {error ? <p className="banner bad" role="alert">{error}</p> : null}
      {props.connection.checkedAt || props.connection.diagnostics.length ? (
        <div className={`connection-summary ${copy.tone}`}>
          <p><strong>{copy.title}</strong> <span className="meta">{copy.detail}</span></p>
          {props.connection.serverVersion ? <p className="meta">Server {props.connection.serverVersion} · checked {new Date(props.connection.checkedAt ?? Date.now()).toLocaleString()}</p> : null}
          <Diagnostics status={props.connection} />
        </div>
      ) : null}
      {selectedModel ? <p className="note">Current selection: {modelLabel(selectedModel)}{selected?.variant ? ` · variant ${selected.variant}` : " · model default"}</p> : null}
    </section>
  );
}

function DiscoverySummary({ discovery }: { discovery: OpenCodeDiscovery }) {
  return (
    <div className="discovery-summary">
      <p className="note">
        OpenCode {discovery.server.version} · {discovery.models.length} model(s) · {discovery.providers.length} provider(s) ·{" "}
        {discovery.agents.length} agent(s)
      </p>
      {discovery.providers.map((provider) => (
        <p key={provider.id} className={provider.ready === "ready" ? "meta" : "meta warn-text"}>
          {provider.name}: {provider.ready === "ready" ? "ready" : provider.ready === "needs_auth" ? "needs OpenCode authentication" : "availability inferred"} — {provider.detail}
        </p>
      ))}
    </div>
  );
}

export function Diagnostics({ status }: { status: ConnectionStatus }) {
  if (status.diagnostics.length === 0) return <p className="note good-text"><CheckCircle2 size={14} aria-hidden="true" /> No connection issues were reported.</p>;
  return (
    <ul className="diagnostics">
      {status.diagnostics.map((diagnostic) => (
        <li key={`${diagnostic.code}-${diagnostic.message}`} className={diagnostic.severity}>
          <AlertTriangle size={15} aria-hidden="true" />
          <span>
            <strong>{diagnostic.title}</strong>
            <span>{diagnostic.message}</span>
            <span className="repair">Repair: {diagnostic.repair}</span>
          </span>
        </li>
      ))}
    </ul>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Activity,
  ChevronDown,
  CircleDollarSign,
  GitFork,
  ListChecks,
  RefreshCw,
  ShieldCheck,
  Square,
  Wrench,
} from "lucide-react";
import type {
  ConnectionStatus,
  OpenCodeDiscovery,
  SessionSummary,
  SessionUsage,
} from "../shared/opencode.ts";
import {
  ApiError,
  cancelRun,
  clearRevert,
  commitRevert,
  compactSession,
  findSelectedModel,
  forkSession,
  interruptSession,
  listSessions,
  loadExport,
  loadPermissions,
  loadUsage,
  modelKey,
  replyPermission,
  resumeSession,
  selectModel,
  stageRevert,
  type WorkshopProject,
} from "./api.ts";
import { Diagnostics, formatTokens, modelLabel } from "./onboarding.tsx";

export function OpenCodePanel(props: {
  connection: ConnectionStatus;
  project: WorkshopProject;
  onConnection: (status: ConnectionStatus) => void;
  onProject: (project: WorkshopProject) => void;
  onOpenSetup: () => void;
}) {
  const discovery = props.connection.discovery;
  const selectedModel = findSelectedModel(discovery, props.project.engine.model);
  const [modelKey, setModelKey] = useState(selectedModel?.key ?? "");
  const [variant, setVariant] = useState(props.project.engine.model?.variant ?? "");
  const [sessions, setSessions] = useState<SessionSummary[]>([]);
  const [usage, setUsage] = useState<SessionUsage | null>(null);
  const [permissions, setPermissions] = useState<Array<{ id: string; sessionID: string; action: string; resources: string[]; message: string | null }>>([]);
  const [revertMessages, setRevertMessages] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const chosen = discovery?.models.find((model) => model.key === modelKey) ?? null;
  const grouped = useMemo(() => {
    const map = new Map<string, typeof discovery.models>();
    for (const model of discovery?.models.filter((candidate) => candidate.availability === "available") ?? []) {
      const list = map.get(model.providerID) ?? [];
      list.push(model);
      map.set(model.providerID, list);
    }
    return [...map.entries()];
  }, [discovery]);

  useEffect(() => {
    setModelKey(selectedModel?.key ?? "");
    setVariant(props.project.engine.model?.variant ?? "");
  }, [selectedModel?.key, props.project.engine.model?.variant]);

  async function refresh() {
    if (!discovery) return;
    setBusy("refresh");
    setError(null);
    try {
      const [sessionResult, usageResult, permissionResult] = await Promise.all([
        listSessions(),
        loadUsage(),
        loadPermissions(),
      ]);
      setSessions(sessionResult.sessions);
      setUsage(usageResult);
      setPermissions(permissionResult.permissions);
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : "The OpenCode panel could not refresh.");
    } finally {
      setBusy(null);
    }
  }

  useEffect(() => {
    void refresh();
    // Refresh once when the panel first mounts. Manual refresh avoids noisy polling.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function saveModel() {
    if (!chosen) return;
    setBusy("model");
    setError(null);
    try {
      const result = await selectModel(props.project, {
        providerID: chosen.providerID,
        id: chosen.id,
        variant: variant || null,
      });
      props.onProject(result.project);
      setNote(`Saved ${chosen.providerID}/${chosen.id}${variant ? `#${variant}` : ""}. The next run records this model.`);
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : "The model could not be saved.");
    } finally {
      setBusy(null);
    }
  }

  async function sessionAction(label: string, work: () => Promise<unknown>) {
    setBusy(label);
    setError(null);
    setNote(null);
    try {
      const result = await work();
      setNote(`${label}: ${typeof result === "string" ? result : JSON.stringify(result)}`);
      await refresh();
    } catch (caught) {
      setError(caught instanceof ApiError ? caught.message : `${label} failed.`);
    } finally {
      setBusy(null);
    }
  }

  async function permissionDecision(request: { id: string; sessionID: string }, decision: "once" | "always" | "reject") {
    await sessionAction("Permission reply", () => replyPermission({
      sessionID: request.sessionID,
      requestID: request.id,
      decision,
    }));
  }

  return (
    <details className="advanced" id="opencode-panel">
      <summary><Wrench size={18} aria-hidden="true" /> OpenCode settings and controls <ChevronDown size={16} aria-hidden="true" /></summary>
      <div className="advanced-body">
        <div className="advanced-head">
          <span className={`state-pill ${props.connection.state}`}>{props.connection.state.replaceAll("_", " ")}</span>
          <span className="meta">
            {props.connection.baseUrl ?? "No URL configured"} · {props.connection.serverVersion ?? "version unknown"} · {props.connection.managed ? "managed by deployment" : "local configuration"}
          </span>
          <button className="action secondary" type="button" disabled={busy !== null} onClick={() => void refresh()}>
            <RefreshCw size={15} aria-hidden="true" /> Refresh
          </button>
          <button className="action secondary" type="button" onClick={props.onOpenSetup}>Connection setup</button>
        </div>

        {error ? <p className="banner bad" role="alert">{error}</p> : null}
        {note ? <p className="banner good" role="status">{note}</p> : null}
        <Diagnostics status={props.connection} />

        <section className="advanced-section">
          <h3><SparkleIcon /> Model and reasoning</h3>
          {discovery ? (
            <>
              <div className="inline-fields">
                <label>
                  Available model
                  <select value={modelKey} onChange={(event) => { setModelKey(event.target.value); setVariant(""); }}>
                    <option value="">Choose a model</option>
                    {grouped.map(([provider, models]) => (
                      <optgroup key={provider} label={provider}>
                        {models?.map((model) => <option key={model.key} value={model.key}>{modelLabel(model)}</option>)}
                      </optgroup>
                    ))}
                  </select>
                </label>
                <label>
                  Variant
                  <select value={variant} onChange={(event) => setVariant(event.target.value)} disabled={!chosen}>
                    <option value="">Model default</option>
                    {(chosen?.variants ?? []).map((id) => <option key={id} value={id}>{id}</option>)}
                  </select>
                </label>
                <button className="action" type="button" disabled={!chosen || busy !== null} onClick={() => void saveModel()}>Save model</button>
              </div>
              {chosen ? (
                <p className="meta">
                  {chosen.pricing === "free" ? "Free" : chosen.pricing === "paid" ? "Paid" : "Price not reported"} · context {formatTokens(chosen.limits.context)} · output {formatTokens(chosen.limits.output)} ·{" "}
                  {chosen.tools ? "tools supported" : "no tool support"} · {chosen.modalities.input.join("/")} input · {chosen.local ? "local provider" : "remote/unknown locality"}
                </p>
              ) : null}
              <p className="note">Only variants returned for the chosen model appear here. Model changes take effect on the next run; an in-flight session keeps its own model.</p>
            </>
          ) : <p className="note">Connection discovery is unavailable. Reconnect to inspect models.</p>}
        </section>

        <section className="advanced-section">
          <h3><ShieldCheck size={17} aria-hidden="true" /> Agents, roles, and permissions</h3>
          {discovery ? (
            <>
              <ul className="compact-list">
                {discovery.roles.map((role) => (
                  <li key={role.role}><strong>{role.role}</strong> → {role.agent}{role.available ? "" : " (fallback/unavailable)"}<span className="meta"> {role.detail}</span></li>
                ))}
              </ul>
              <p className="meta">Visible OpenCode agents: {discovery.agents.map((agent) => `${agent.name} (${agent.mode})`).join(", ") || "none reported"}</p>
              <h4>Pending permission requests</h4>
              {permissions.length === 0 ? <p className="note">No pending request is reported for this project.</p> : (
                <ul className="permission-list">
                  {permissions.map((request) => (
                    <li key={request.id}>
                      <span><strong>{request.action}</strong> {request.resources.join(", ")}{request.message ? ` — ${request.message}` : ""}</span>
                      <span className="permission-actions">
                        <button type="button" disabled={busy !== null} onClick={() => void permissionDecision(request, "once")}>Allow once</button>
                        <button type="button" disabled={busy !== null} onClick={() => void permissionDecision(request, "always")}>Always</button>
                        <button type="button" className="danger" disabled={busy !== null} onClick={() => void permissionDecision(request, "reject")}>Reject</button>
                      </span>
                    </li>
                  ))}
                </ul>
              )}
              <p className="note">Replies are sent to OpenCode for a request owned by this project. Unfinished Business never auto-approves a request.</p>
            </>
          ) : null}
        </section>

        <section className="advanced-section">
          <h3><ListChecks size={17} aria-hidden="true" /> Discovered harness capabilities</h3>
          {discovery ? (
            <>
              <ul className="capability-grid">
                {discovery.capabilities.map((capability) => (
                  <li key={capability.id} className={capability.supported ? "supported" : "deferred"}>
                    <strong>{capability.label}</strong>
                    <span>{capability.supported ? "supported" : "deferred"}</span>
                    <span className="meta">{capability.detail}</span>
                  </li>
                ))}
              </ul>
              <div className="discovery-columns">
                <div><h4>Commands</h4><p className="meta">{discovery.commands.map((command) => `/${command.name}${command.description ? ` — ${command.description}` : ""}`).join(" · ") || "none"}</p></div>
                <div><h4>Skills</h4><p className="meta">{discovery.skills.map((skill) => skill.name).join(", ") || "none"}</p></div>
                <div><h4>MCP servers</h4><p className="meta">{discovery.mcpServers.map((server) => `${server.name}: ${server.status}`).join(" · ") || "none"}</p></div>
                <div><h4>Formatters / LSP</h4><p className="meta">{discovery.formatters.map((item) => item.name).join(", ") || "no formatter config"} · {discovery.lspServers.map((item) => item.name).join(", ") || "no LSP config"}</p></div>
              </div>
            </>
          ) : null}
        </section>

        <section className="advanced-section">
          <h3><CircleDollarSign size={17} aria-hidden="true" /> Usage, tokens, and cost</h3>
          {usage?.supported ? (
            <p className="meta">
              {usage.sessions.length} session(s) · cost {usage.totals.cost.toFixed(4)} USD · input {usage.totals.tokens.input} · output {usage.totals.tokens.output} · reasoning {usage.totals.tokens.reasoning}
            </p>
          ) : <p className="note">OpenCode has not reported usage for a project-owned session yet. Usage is shown only when the provider returns it.</p>}
          <p className="note">Quota and balance are not available from the OpenCode HTTP API. {usage?.detail}</p>
          <p className="meta">
            {usage?.links.length ? usage.links.map((link) => <a key={link.url} href={link.url} target="_blank" rel="noreferrer">{link.label}</a>) : "No provider usage link is known for this catalog."}
          </p>
        </section>

        <section className="advanced-section">
          <h3><Activity size={17} aria-hidden="true" /> Project sessions</h3>
          <p className="note">Only sessions referenced by this project are listed. Actions are checked against that ownership before they reach OpenCode.</p>
          {sessions.length === 0 ? <p className="note">No session has been created for this project yet.</p> : (
            <ul className="session-list">
              {sessions.map((session) => (
                <li key={session.id}>
                  <div>
                    <strong>{session.role}</strong> <span className="meta">{session.id} · {session.title ?? "untitled"} · {session.model ?? "model not reported"}</span>
                    <p className="meta">
                      {session.messageCount} message(s) · {session.outcome ?? "outcome unknown"} · cost {session.cost.toFixed(4)} · {session.idle ? "idle" : "possibly active"}
