            const exported = await loadExport();
            return `${exported.limitation} ${exported.plan ? "Compiled plan is ready." : "Plan is not fully approved."} Engine: ${modelKey(exported.engine.model) ?? "no model selected"}.`;
          })}>Check export</button>
        </section>
      </div>
    </details>
  );
}

